INSERT INTO public.offers (id, tenant_id, kind, partner_id, category, status, slug, title, teaser, body, details, hero_image, gallery, fulfillment, booking_url, price, duration_minutes, cancellation, commission, availability, featured, sort_order, source_locale, translation_state, first_published_at, created_at, updated_at) VALUES ('7c3e2a10-1b2c-4d5e-8f90-0a1b2c3d0001', 'unique-places', 'house-service', NULL, 'arrival-departure', 'published', '{"de": "frueher-einchecken", "en": "early-check-in"}', '{"de": "Früher ankommen", "en": "Arrive earlier"}', '{"de": "Das Apartment wartet schon auf Dich – ab 12 Uhr statt ab 16 Uhr.", "en": "Your apartment is ready for you – from noon instead of 4 pm."}', '{"de": "Wer früh losfährt, soll nicht vor verschlossener Tür stehen. Wir bereiten Dein Apartment so vor, dass Du schon mittags ankommen kannst – Gepäck abstellen, Kaffee kochen, durchatmen.", "en": "If you set off early, you shouldn''t have to wait outside. We prepare your apartment so you can arrive at noon – drop your bags, make a coffee, breathe."}', '{"de": "Ab 12:00 Uhr am Anreisetag\nNach Verfügbarkeit des Apartments", "en": "From 12:00 on the day of arrival\nSubject to apartment availability"}', NULL, '[]', 'instant', NULL, NULL, NULL, '{"type": "free-until", "hoursBefore": 48}', NULL, '{"phases": ["before-arrival", "arrival-day"], "seasons": [], "weekdays": [], "focusPhases": ["before-arrival", "arrival-day"]}', true, 10, 'de', '{}', '2026-11-08 12:24:15.624+00', '2026-11-08 12:24:15.624831+00', '2026-11-08 12:24:15.624831+00') ON CONFLICT DO NOTHING;
