INSERT INTO public.offers (id, tenant_id, kind, partner_id, category, status, slug, title, teaser, body, details, hero_image, gallery, fulfillment, booking_url, price, duration_minutes, cancellation, commission, availability, featured, sort_order, source_locale, translation_state, first_published_at, created_at, updated_at) VALUES ('7c3e2a10-1b2c-4d5e-8f90-0a1b2c3d0006', 'unique-places', 'partner', '5d0f0b8e-4a8a-4f0e-9b7e-0b7d2f1a0001', 'food-drink', 'published', '{"de": "kaeserei-besuch", "en": "dairy-visit"}', '{"de": "Ein Vormittag in der Sennerei", "en": "A morning at the dairy"}', '{"de": "Zuschauen, wie Bergkäse entsteht – und danach probieren. (Beispielangebot)", "en": "Watch mountain cheese being made – then taste it. (Sample offer)"}', '{"de": "Früh am Morgen wird die Milch der umliegenden Höfe verarbeitet. Die Sennerin zeigt Dir den Kessel, den Keller und erzählt, warum ein Laib zwölf Monate reifen darf.\n\nZum Abschluss gibt es eine Verkostung mit Brot und Most.", "en": "Early in the morning the milk from the surrounding farms is processed. The cheesemaker shows you the vat and the cellar and tells you why a wheel may mature for twelve months.\n\nTo finish, a tasting with bread and cider."}', '{"de": "Dienstag bis Samstag, 9:30 Uhr\nDauer etwa zwei Stunden\nAnfrage über UNIQUE PLACES", "en": "Tuesday to Saturday, 9:30\nAbout two hours\nRequest via UNIQUE PLACES"}', NULL, '[]', 'request', NULL, '{"model": "per-person", "currency": "EUR", "amountCents": 2400}', 120, '{"type": "free-until", "hoursBefore": 24}', '{"type": "percent", "basisPoints": 1000}', '{"phases": ["before-arrival", "arrival-day", "in-stay"], "seasons": [], "weekdays": [2, 3, 4, 5, 6], "focusPhases": ["in-stay"]}', true, 10, 'de', '{}', '2026-11-08 12:24:15.654+00', '2026-11-08 12:24:15.654486+00', '2026-11-08 12:24:15.654486+00') ON CONFLICT DO NOTHING;
INSERT INTO public.offers (id, tenant_id, kind, partner_id, category, status, slug, title, teaser, body, details, hero_image, gallery, fulfillment, booking_url, price, duration_minutes, cancellation, commission, availability, featured, sort_order, source_locale, translation_state, first_published_at, created_at, updated_at) VALUES ('7c3e2a10-1b2c-4d5e-8f90-0a1b2c3d0007', 'unique-places', 'partner', '5d0f0b8e-4a8a-4f0e-9b7e-0b7d2f1a0002', 'nature', 'published', '{"de": "sonnenaufgang-am-grat", "en": "sunrise-on-the-ridge"}', '{"de": "Sonnenaufgang am Grat", "en": "Sunrise on the ridge"}', '{"de": "Mit einem Bergführer zum ersten Licht – kleine Gruppe, leichter Weg. (Beispielangebot)", "en": "With a mountain guide to the first light – small group, easy path. (Sample offer)"}', '{"de": "Aufbruch in der Dunkelheit, Stirnlampe, Stille. Oben angekommen färbt sich der Himmel über den Gipfeln – dazu heißer Tee aus der Thermoskanne.", "en": "Setting off in the dark, a head torch, silence. At the top the sky above the peaks turns colour – with hot tea from a flask."}', '{"de": "Treffpunkt am Parkplatz Talstation\nDauer etwa vier Stunden\nGute Schuhe erforderlich", "en": "Meeting point: valley station car park\nAbout four hours\nSturdy shoes required"}', NULL, '[]', 'link', 'https://example.org/bergfuehrer/sonnenaufgang', '{"model": "from", "currency": "EUR", "amountCents": 4900}', 240, '{"type": "partner-terms"}', NULL, '{"phases": ["before-arrival", "in-stay"], "seasons": [{"to": "10-31", "from": "05-01"}], "weekdays": [], "focusPhases": ["in-stay"]}', false, 20, 'de', '{}', '2026-11-08 12:24:15.658+00', '2026-11-08 12:24:15.65829+00', '2026-11-08 12:24:15.65829+00') ON CONFLICT DO NOTHING;
